WITH anchor AS ( SELECT m.ltbase_row_id AS row_id FROM "entity_main" m WHERE m.ltbase_schema_id = $1 AND ((m."integer_01" > $2::bigint) AND (EXISTS (SELECT 1 FROM "eav_data" x WHERE x.schema_id = m.ltbase_schema_id AND x.row_id = m.ltbase_row_id AND x.attr_id = $3 AND x.value_text = $4))) UNION -- Include real-time buffer rows from change_log (flushed_at = 0) -- while preserving the same anchor filter semantics. SELECT cl.row_id FROM "change_log" cl WHERE cl.schema_id = $1 AND cl.flushed_at = 0 AND EXISTS ( SELECT 1 FROM "entity_main" m WHERE m.ltbase_schema_id = $1 AND m.ltbase_row_id = cl.row_id AND ((m."integer_01" > $2::bigint) AND (EXISTS (SELECT 1 FROM "eav_data" x WHERE x.schema_id = m.ltbase_schema_id AND x.row_id = m.ltbase_row_id AND x.attr_id = $3 AND x.value_text = $4))) ) ), keys AS ( SELECT a.row_id , ( SELECT m.bigint_01 FROM "entity_main" m WHERE m.ltbase_schema_id = $1 AND m.ltbase_row_id = a.row_id LIMIT 1 ) AS k0, COUNT(*) OVER() AS total FROM anchor a ), ordered AS ( SELECT row_id , k0, total FROM keys ORDER BY k0 ASC, row_id LIMIT $5 OFFSET $6 ), main_data AS ( SELECT ltbase_schema_id, ltbase_row_id, ltbase_created_at, ltbase_updated_at, ltbase_deleted_at, ltbase_created_by, ltbase_deleted_by, ltbase_updated_by, text_01, text_02, text_03, text_04, text_05, text_06, text_07, text_08, text_09, text_10, smallint_01, smallint_02, smallint_03, integer_01, integer_02, integer_03, bigint_01, bigint_02, bigint_03, double_01, double_02, double_03, uuid_01, uuid_02, o.total , o.k0 FROM ordered o INNER JOIN "entity_main" m ON m.ltbase_schema_id = $1 AND m.ltbase_row_id = o.row_id ), eav_aggregated AS ( SELECT e.row_id, JSON_AGG( JSON_BUILD_OBJECT( 'schema_id', e.schema_id, 'row_id', e.row_id, 'attr_id', e.attr_id, 'array_indices', e.array_indices, 'value_text', e.value_text, 'value_numeric', e.value_numeric ) ORDER BY e.attr_id, e.array_indices )::TEXT AS attributes_json FROM ordered o INNER JOIN "eav_data" e ON e.schema_id = $1 AND e.row_id = o.row_id GROUP BY e.row_id ) SELECT ltbase_schema_id, ltbase_row_id, ltbase_created_at, ltbase_updated_at, ltbase_deleted_at, ltbase_created_by, ltbase_deleted_by, ltbase_updated_by, text_01, text_02, text_03, text_04, text_05, text_06, text_07, text_08, text_09, text_10, smallint_01, smallint_02, smallint_03, integer_01, integer_02, integer_03, bigint_01, bigint_02, bigint_03, double_01, double_02, double_03, uuid_01, uuid_02, COALESCE(e.attributes_json, '[]') AS attributes_json, m.total AS total_records, CEIL(m.total::numeric / NULLIF($5::numeric, 0)) AS total_pages, (FLOOR($6::numeric / NULLIF($5::numeric, 0)) + 1)::int AS current_page FROM main_data m LEFT JOIN eav_aggregated e ON e.row_id = m.ltbase_row_id ORDER BY m.k0 ASC, m.ltbase_row_id;
